package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;

/** A grade given to several people at once. Each person is saved in their own transaction, through
 * {@link PersonService#update}, exactly as the person form saves them (keeping their name and terms),
 * so each records its own PERSON_EDITED and rollup lines. A viewer's bulk grade, or one on an archived
 * sheet, goes through with nothing done: no one is changed. */
@Service
public class PersonBulkService {

    private final PersonService service;
    private final PersonRepository people;
    private final SettingsService settings;
    private final SheetRepository sheets;

    public PersonBulkService(PersonService service, PersonRepository people, SettingsService settings,
            SheetRepository sheets) {
        this.service = service;
        this.people = people;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Gives each of the people {@code grade} from {@code from} (the sheet's today when left out), in
     * list order; those not on the sheet, or saved by someone else while
     * this runs, are left as they are. The people it changed. */
    public List<Person> grade(String sheetId, String user, Collection<Long> personIds, String grade, LocalDate from) {
        Set<Long> asked = Set.copyOf(personIds);
        if (settings.roleOf(sheetId, user) == Role.VIEWER) return List.of();
        if (sheets.findById(sheetId).map(Sheet::isArchived).orElse(false)) return List.of();
        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .filter(p -> asked.contains(p.getId()))
                .toList();
        List<Person> changed = new ArrayList<>();
        for (Person person : listed) {
            try {
                changed.add(service.update(sheetId, user, person.getId(), person.getVersion(), person.getName(),
                        grade, from, person.getTerms(), person.getContact()));
            } catch (PersonStaleException | PersonNotFoundException | ObjectOptimisticLockingFailureException e) {
                // Left as it is.
            }
        }
        return changed;
    }
}
package net.officefloor.hq.app.settings;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/** Refuses every change a viewer asks of a sheet before it reaches its controller, so it writes nothing.
 * Reads go through, as does loading the sheet; a bulk change goes through to {@code ClaimBulkService},
 * which refuses each claim a viewer asks of it. */
@Configuration
public class ViewerGuard implements WebMvcConfigurer, HandlerInterceptor {

    private final SettingsService settings;

    public ViewerGuard(SettingsService settings) {
        this.settings = settings;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this)
                .addPathPatterns("/api/sheets/*/**")
                .excludePathPatterns("/api/sheets/*/load", "/api/sheets/*/claims/bulk-*",
                        "/api/sheets/*/people/bulk-grade");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) return true;
        String user = request.getHeader("X-User");
        String sheetId = sheetId(request);
        if (user == null || user.isBlank() || sheetId == null) return true;
        if (settings.roleOf(sheetId.trim(), user.trim()) == Role.VIEWER) throw new ViewerRefusedException();
        return true;
    }

    @SuppressWarnings("unchecked")
    private static String sheetId(HttpServletRequest request) {
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(vars instanceof Map<?, ?> map)) return null;
        Object id = map.containsKey("sheetId") ? map.get("sheetId") : map.get("id");
        return id == null ? null : id.toString();
    }
}
